  const form = document.querySelector('form');
  if (!form) return 'No form found';
  const inputs = form.querySelectorAll('input, select, textarea');
  const result = [];
  inputs.forEach(el => {
    result.push({
      tag: el.tagName,
      type: el.type,
      name: el.name,
      id: el.id,
      placeholder: el.placeholder,
      value: el.value,
      className: el.className
    });
  });
  return JSON.stringify(result);
}

